package com.example.habitzone.command;
import com.example.habitzone.domain.HabitPriority; import com.example.habitzone.usecase.SetHabitPriorityUseCase; import java.util.Objects;
public final class SetPriorityCommand implements Command { private final SetHabitPriorityUseCase useCase; public SetPriorityCommand(SetHabitPriorityUseCase useCase){this.useCase=Objects.requireNonNull(useCase);} public String name(){return "set-priority";} public String usage(){return "set-priority HABIT_NAME low|normal|high";} public CommandResult execute(String args){String a=args==null?"":args.trim();int i=a.lastIndexOf(' ');if(i<=0)return CommandResult.failure(CommandMessages.MISSING_HABIT_NAME);try{HabitPriority p=HabitPriority.valueOf(a.substring(i+1).toUpperCase());return CommandSupport.executeUseCase(()->useCase.execute(a.substring(0,i),p),h->CommandResult.success("Set priority for '"+h.name()+"'."));}catch(IllegalArgumentException e){return CommandResult.failure("Please provide a priority: low, normal, or high.");}}}
